/**
 * Regenerate the checked-in JSON Schema snapshot of every TS↔Python
 * boundary contract:
 *
 *   bun --filter @applyso/validation snapshot-json-schema
 *
 * CI diffs the snapshot; Python tests can load it to validate sample
 * payloads against the same shapes the TypeScript boundary enforces.
 */
import { allContractJsonSchemas } from '../src/json-schema.ts';

const snapshot = {
  $comment:
    'Generated by @applyso/validation — do not edit by hand. See scripts/snapshot-json-schema.ts.',
  contracts: allContractJsonSchemas(),
};

await Bun.write(
  new URL('../contracts.snapshot.json', import.meta.url),
  `${JSON.stringify(snapshot, null, 2)}\n`,
);

console.log(
  `Wrote contracts.snapshot.json (${Object.keys(snapshot.contracts).length} contracts)`,
);
